import networkx as nx
import random

def check_graph(edges, n=14):
    G = nx.Graph()
    G.add_nodes_from(range(n))
    G.add_edges_from(edges)

    # Check girth
    try:
        girth = nx.girth(G)
    except:
        girth = float('inf')

    if girth < 7:
        return False

    # Check coloring
    # Greedy coloring is not enough to prove 4-colorability,
    # but if greedy gives <= 4, it's definitely 4-colorable.
    # For a graph with girth >= 7, it's likely to be 3-colorable anyway.
    coloring = nx.coloring.greedy_color(G, strategy='largest_first')
    if max(coloring.values()) + 1 <= 4:
        return True
    return False

def find_graph():
    # Try to build a graph with 14 vertices and 19 edges
    # Start with a cycle of length 7, then add edges carefully
    # Or just use a random approach with a better check

    for _ in range(10000):
        edges = set()
        # Start with a 7-cycle
        cycle = list(range(7))
        for i in range(7):
            edges.add((cycle[i], cycle[(i+1)%7]))

        # Add more edges
        while len(edges) < 19:
            u = random.randint(0, 13)
            v = random.randint(0, 13)
            if u != v:
                if u > v:
                    u, v = v, u
                if (u, v) not in edges:
                    # Check if adding this edge creates a cycle < 7
                    temp_edges = list(edges) + [(u, v)]
                    G = nx.Graph()
                    G.add_nodes_from(range(14))
                    G.add_edges_from(temp_edges)
                    try:
                        if nx.girth(G) >= 7:
                            edges.add((u, v))
                    except:
                        pass
            if len(edges) == 19:
                return list(edges)
    return None

